// Apply corporate native metadata to the project generated by the pinned Tauri CLI.
import { readFile, writeFile, copyFile, mkdir } from 'node:fs/promises';
const root = new URL('../', import.meta.url);
const pkg = JSON.parse(await readFile(new URL('package.json', root), 'utf8'));
const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(pkg.version);
if (!match) throw new Error('Android release requires a numeric major.minor.patch version');
const [, major, minor, patch] = match.map(Number);
if (minor > 999 || patch > 999) throw new Error('Android version component exceeds three digits');
const versionCode = major * 1000000 + minor * 1000 + patch;
if (versionCode < 1 || versionCode > 2100000000) throw new Error('Android version code outside valid range');
const app = new URL('src-tauri/gen/android/app/', root);
const gradle = new URL('build.gradle.kts', app);
let source = await readFile(gradle, 'utf8');
for (const [key,value] of [['versionCode', String(versionCode)], ['versionName', pkg.version]]) {
  const pattern = new RegExp(`getProperty\\("tauri\\.android\\.${key}", "[^"]*"\\)`, 'g');
  if (!source.match(pattern)) throw new Error(`Unsupported Android template: missing ${key}`);
  source = source.replace(pattern, `getProperty("tauri.android.${key}", "${value}")`);
}
if (!source.includes('CINNY_ANDROID_DEBUG_KEYSTORE')) {
  source = source.replace('    buildTypes {', `    // CI uses a disposable, explicitly located preview key, never a production key.
    System.getenv("CINNY_ANDROID_DEBUG_KEYSTORE")?.let { debugKey ->
        signingConfigs.getByName("debug") {
            storeFile = file(debugKey)
            storePassword = "android"
            keyAlias = "androiddebugkey"
            keyPassword = "android"
        }
    }
    buildTypes {`);
}
await writeFile(gradle, source);
await writeFile(new URL('tauri.properties', app), `tauri.android.versionCode=${versionCode}\ntauri.android.versionName=${pkg.version}\n`);
const java = new URL('src/main/java/in/cinny/app/', app);
await mkdir(java, { recursive: true });
for (const name of ['CorpPlugin.kt', 'MainActivity.kt']) {
  await copyFile(new URL('src-tauri/android/'+name, root), new URL(name, java));
}
const drawable = new URL('src/main/res/drawable/', app);
await mkdir(drawable, { recursive: true });
await copyFile(new URL('src-tauri/android/ic_stat_cinny.xml', root), new URL('ic_stat_cinny.xml', drawable));
console.log(`Android ${pkg.version} (versionCode ${versionCode}) prepared`);
